      "type": "array",
      "items": {}
    },
    "reasoning_summary": {
      "type": "string",
      "minLength": 1
    }
  },
  "additionalProperties": false,
  "$defs": {
    "JudgeBusinessExpectationOutput": {
      "type": "object",
      "properties": {
        "expectation_id": {
