          "minLength": 1
        }
      },
      "additionalProperties": false,
      "required": [
        "expectation_id",
        "blocking"
      ]
    },
    "JudgeFulfillmentAssessmentOutput": {
      "type": "object",
      "properties": {
        "expectation_id": {
          "type": "string",
          "minLength": 1
        },
        "status": {
          "type": "string",
          "minLength": 1
        },
        "score": {
          "type": [
            "number",
            "null"
          ]
        },
        "expected_evidence": {
          "type": "array",
          "items": {}
        },
        "actual_evidence": {
          "type": "array",
          "items": {}
        },
        "downstream_impact": {
          "type": "string",
          "minLength": 1
        },
        "authority_tool_call_ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      },
      "additionalProperties": false,
      "required": [
        "expectation_id",
        "status"
      ]
    },
    "GapItem": {
      "type": "object",
      "properties": {
        "kind": {
          "type": "string",
          "minLength": 1
        },
        "error_type": {
          "type": "string",
          "minLength": 1
        },
        "expected": {},
        "actual": {},
        "evidence_ref": {
          "type": "string",
          "minLength": 1
        },
        "raw": {},
        "incomplete": {
          "type": "boolean"
        }
      },
      "additionalProperties": false
    }
  },
  "required": [
    "expected",
    "business_expectations",
    "reasoning_summary"
  ]
